import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().start();
    }

    void start() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] basePoly = new int[10];
        for (int i = 0; i < k; i++) {
            basePoly[in.nextInt()] = 1;
        }
        int[] resultPoly = new int[]{1};
        int power = n / 2;
        while (true) {
            if ((power & 1) == 1) {
                resultPoly = multiply(resultPoly, basePoly, MOD);
            }
            power >>>= 1;
            if (power == 0) break;
            basePoly = multiply(basePoly, basePoly, MOD);
        }
        long answer = 0;
        for (int coefficient : resultPoly) {
            answer = (answer + (long)coefficient * coefficient) % MOD;
        }
        out.println(answer);
        out.close();
    }

    int[] multiply(int[] p1, int[] p2, int mod) {
        int degree = p1.length + p2.length - 1;
        int n = 1;
        while (n < degree) n <<= 1;

        double[] re1 = new double[n];
        double[] im1 = new double[n];
        for (int i = 0; i < p1.length; i++) {
            long val = ((long)p1[i] % mod + mod) % mod;
            re1[i] = val & 0x7FFF;
            im1[i] = val >>> 15;
        }

        fft(re1, im1, false);

        double[] re2 = new double[n];
        double[] im2 = new double[n];
        if (p1 == p2) {
            System.arraycopy(re1, 0, re2, 0, n);
            System.arraycopy(im1, 0, im2, 0, n);
        } else {
            for (int i = 0; i < p2.length; i++) {
                long val = ((long)p2[i] % mod + mod) % mod;
                re2[i] = val & 0x7FFF;
                im2[i] = val >>> 15;
            }
            fft(re2, im2, false);
        }

        double[] resRe = new double[n];
        double[] resIm = new double[n];
        double factor = 0.25 / n;

        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);

            double a1r = re1[i] + re1[j];
            double a1i = im1[i] - im1[j];
            double a2r = im1[i] + im1[j];
            double a2i = re1[j] - re1[i];

            double b1r = re2[i] + re2[j];
            double b1i = im2[i] - im2[j];
            double b2r = im2[i] + im2[j];
            double b2i = re2[j] - re2[i];

            resRe[i] = (a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r) * factor;
            resIm[i] = (a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i) * factor;
        }

        fft(resRe, resIm, true);

        int[] product = new int[degree];
        for (int i = 0; i < degree; i++) {
            long realPart = Math.round(resRe[i]);
            long imagPart = Math.round(resIm[i]);
            long low = realPart % mod;
            long high = imagPart % mod;
            product[i] = (int)((low + (high << 15)) % mod);
        }
        return product;
    }

    void fft(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >>> 1;
            for (; (j & bit) != 0; bit >>>= 1) j ^= bit;
            j ^= bit;
            if (i < j) {
                double temp = re[i]; re[i] = re[j]; re[j] = temp;
                temp = im[i]; im[i] = im[j]; im[j] = temp;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >>> 1;
            double[] cosines = new double[half];
            double[] sines = new double[half];
            for (int i = 0; i < half; i++) {
                double angle = 2 * Math.PI * i / len * (inverse ? -1 : 1);
                cosines[i] = Math.cos(angle);
                sines[i] = Math.sin(angle);
            }

            for (int i = 0; i < n; i += len) {
                for (int k = 0; k < half; k++) {
                    double cr = re[i + k + half] * cosines[k] - im[i + k + half] * sines[k];
                    double ci = re[i + k + half] * sines[k] + im[i + k + half] * cosines[k];

                    double ur = re[i + k];
                    double ui = im[i + k];

                    re[i + k] = ur + cr;
                    im[i + k] = ui + ci;
                    re[i + k + half] = ur - cr;
                    im[i + k + half] = ui - ci;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream input;
        private final byte[] buffer = new byte[1024];
        private int index, count;

        public InputReader(InputStream input) {
            this.input = input;
        }

        private int getByte() {
            if (count == -1) throw new InputMismatchException();
            if (index >= count) {
                index = 0;
                try { count = input.read(buffer); } catch (IOException e) { throw new InputMismatchException(); }
                if (count <= 0) return -1;
            }
            return buffer[index++] & 255;
        }

        public int nextInt() {
            int c = getByte();
            while (c <= 32) c = getByte();
            int sign = 1;
            if (c == '-') { sign = -1; c = getByte(); }
            int value = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + c - '0';
                c = getByte();
            }
            return value * sign;
        }
    }
}
